package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class EquivalentFractionScalingTest {
 @Test public void sameFactorBothTermsFromPublicCondition(){for(int[]a:new int[][]{{1,3,4},{3,2,5},{0,10,7},{1,1,12},{100,100,12}}){Question q=EquivalentFractionScaling.make(a[0],a[1],a[2]);q.answers=new String[]{"poison","poison"};q.expression="poison";assertTrue(EquivalentFractionScaling.check(q,List.of(""+(a[0]*a[2]),""+(a[1]*a[2]))).correct());assertEquals(0,EquivalentFractionScaling.check(q,List.of(""+(a[0]*a[2]+1),""+(a[1]*a[2]))).index);assertEquals(1,EquivalentFractionScaling.check(q,List.of(""+(a[0]*a[2]),""+(a[1]*a[2]+1))).index);assertEquals(5,q.studyGuide.frames.size());assertFalse(q.studyGuide.transfer);}}
 @Test public void reducedValueOrUnequalFactorsDoNotReplaceRequiredRewrite(){Question q=EquivalentFractionScaling.make(1,3,4);assertFalse(EquivalentFractionScaling.check(q,List.of("1","3")).correct());assertFalse(EquivalentFractionScaling.check(q,List.of("4/12","12")).correct());q.prompt=q.prompt.replace("(3 × 4)","(3 × 5)");assertNull(EquivalentFractionScaling.read(q));assertNull(EquivalentFractionScaling.read(new Question(EquivalentFractionScaling.ID,"1/0 = (1 × 4)/(0 × 4) = □/□\n分子と分母","")));for(int[]a:new int[][]{{1,0,2},{1,3,0},{1000000,2,2}})try{EquivalentFractionScaling.make(a[0],a[1],a[2]);fail();}catch(IllegalArgumentException expected){}}
 @Test public void ordinaryPackHasBothTermInputAndFreshProperImproperSupply(){String pack="na-nied-primary-2024-v1";Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,pack);assertTrue(GlobalCurriculum.pack(p).inGrade(EquivalentFractionScaling.ID,6));assertFalse(Curriculum.inCurriculum(Catalog.get(EquivalentFractionScaling.ID),2022));Generator g=new Generator(new Random(271));List<String>recent=new ArrayList<>();boolean proper=false,improper=false;for(int i=0;i<100;i++){Question q=g.next(EquivalentFractionScaling.ID,recent,false,GlobalCurriculum.limits(pack,EquivalentFractionScaling.ID,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[]v=EquivalentFractionScaling.read(q);proper|=v[0]>0&&v[0]<v[1];improper|=v[0]>v[1];assertTrue(new Checker().check(q,List.of(),List.of(""+v[3],""+v[4])).correct());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(5,h.size());assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}assertTrue(proper&&improper);}
 @Test public void completeSmallDomainBeforeOldest(){CurriculumLimits l=new CurriculumLimits("maxGiven=3;maxResult=9;nonnegative=true");Map<String,Integer>recent=new LinkedHashMap<>();Random r=new Random(271);for(int i=0;i<24;i++){Question q=EquivalentFractionScaling.next(r,l,recent);assertFalse(recent.containsKey(q.signature()));recent.put(q.signature(),i);}assertEquals(24,recent.size());assertEquals(recent.keySet().iterator().next(),EquivalentFractionScaling.next(r,l,recent).signature());}
}
